import{_ as e,o as l,c as i,a2 as n}from"./chunks/framework.CRkTBNIT.js";const f=JSON.parse('{"title":"Architecture Decision Records (ADR Log)","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/decisions.md","filePath":"system-design/decisions.md"}'),d={name:"system-design/decisions.md"};function s(a,t,r,o,g,c){return l(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="architecture-decision-records-adr-log" tabindex="-1">Architecture Decision Records (ADR Log) <a class="header-anchor" href="#architecture-decision-records-adr-log" aria-label="Permalink to &quot;Architecture Decision Records (ADR Log)&quot;">​</a></h1><p>This log records every major architectural and technical decision made during the development of OmniPost (<code>20-notification-delivery-platform</code>).</p><hr><table tabindex="0"><thead><tr><th style="text-align:left;">ADR ID</th><th style="text-align:left;">Decision Title</th><th style="text-align:left;">Status</th><th style="text-align:left;">Deciding Factors</th><th style="text-align:left;">Chosen Solution</th><th style="text-align:left;">Trade-Off Accepted</th><th style="text-align:left;">Revisit When</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>ADR-01</strong></td><td style="text-align:left;">Database Engine Choice</td><td style="text-align:left;"><strong>Accepted</strong></td><td style="text-align:left;">Need for strict ACID unique constraints on <code>(tenant_id, idempotency_key)</code>.</td><td style="text-align:left;">PostgreSQL / SQLite with async SQLAlchemy.</td><td style="text-align:left;">Lower write throughput than Cassandra.</td><td style="text-align:left;">Volume exceeds 500M records.</td></tr><tr><td style="text-align:left;"><strong>ADR-02</strong></td><td style="text-align:left;">Template Sandboxing</td><td style="text-align:left;"><strong>Accepted</strong></td><td style="text-align:left;">Prevention of Server-Side Template Injection (SSTI) attacks.</td><td style="text-align:left;">Jinja2 <code>SandboxedEnvironment</code>.</td><td style="text-align:left;">Slightly higher CPU rendering latency.</td><td style="text-align:left;">Throughput requires pre-compiled bytecode.</td></tr><tr><td style="text-align:left;"><strong>ADR-03</strong></td><td style="text-align:left;">Priority Queue Architecture</td><td style="text-align:left;"><strong>Accepted</strong></td><td style="text-align:left;">Guarantee that 2FA OTP codes bypass marketing broadcasts.</td><td style="text-align:left;">Multi-tier priority queue with lease-based locking.</td><td style="text-align:left;">Database lock contention at high worker concurrency.</td><td style="text-align:left;">Scale exceeds 10,000 concurrent workers.</td></tr><tr><td style="text-align:left;"><strong>ADR-04</strong></td><td style="text-align:left;">Rate Limiting Algorithm</td><td style="text-align:left;"><strong>Accepted</strong></td><td style="text-align:left;">Need to allow legitimate bursts while strictly bounding average RPS.</td><td style="text-align:left;">In-memory Token Bucket rate limiter.</td><td style="text-align:left;">Process-local state rather than shared cluster state.</td><td style="text-align:left;">Multi-node deployment requires Redis.</td></tr><tr><td style="text-align:left;"><strong>ADR-05</strong></td><td style="text-align:left;">Credential Security</td><td style="text-align:left;"><strong>Accepted</strong></td><td style="text-align:left;">Zero-trust protection of third-party API keys in database.</td><td style="text-align:left;">Fernet AES-128 symmetric encryption with log masking.</td><td style="text-align:left;">Key management requires environment variable distribution.</td><td style="text-align:left;">Enterprise deployment adopts AWS KMS / HashiCorp Vault.</td></tr><tr><td style="text-align:left;"><strong>ADR-06</strong></td><td style="text-align:left;">Webhook Authentication</td><td style="text-align:left;"><strong>Accepted</strong></td><td style="text-align:left;">Verification of webhook payload integrity and anti-replay defense.</td><td style="text-align:left;">HMAC-SHA256 timestamped signatures (<code>X-Signature-SHA256</code>).</td><td style="text-align:left;">Receiving clients must implement HMAC verification.</td><td style="text-align:left;">Clients demand mTLS or asymmetric RSA.</td></tr><tr><td style="text-align:left;"><strong>ADR-07</strong></td><td style="text-align:left;">Timezone Quiet Hours</td><td style="text-align:left;"><strong>Accepted</strong></td><td style="text-align:left;">Compliance with telecom quiet-hours laws and Daylight Saving Time.</td><td style="text-align:left;">Native Python 3.9+ <code>zoneinfo</code> module with midnight wrap-around.</td><td style="text-align:left;">Requires system tzdata updates.</td><td style="text-align:left;">Real-time GPS-based geolocation routing needed.</td></tr></tbody></table>',4)])])}const h=e(d,[["render",s]]);export{f as __pageData,h as default};
